        return Math.PI * radius * radius;
    }

    @Override
    void draw() {
        System.out.println("Drawing " + color + " circle of radius " + radius);
    }
}

public class Main {
    public static void main(String[] args) {
        Circle c = new Circle("red", 5.0);
        c.draw();
        System.out.printf("Area: %.2f%n", c.area());

        // Polymorphism – parent reference
        Shape s = new Circle("blue", 3.0);
        s.draw();
        System.out.printf("Area: %.2f%n", s.area());
    }
}
```

**Output:**
```
Drawing red circle of radius 5.0
Area: 78.54
Drawing blue circle of radius 3.0
Area: 28.27
```

