### Time Class with Addition and Display Methods

```java
public class Time {
    private int hour;
    private int minute;

    // Constructors
    public Time() {
        this.hour = 0;
        this.minute = 0;
    }

    public Time(int hour, int minute) {
        this.hour = hour;
        this.minute = minute;
    }

    // Method to display time in HH:MM format
    public void display() {
        System.out.printf("%02d:%02d%n", hour, minute);
    }

    // Method to add two Time objects and return a new Time object
    public Time addition(Time t2) {
        int totalMinutes = this.minute + t2.minute;
        int totalHours = this.hour + t2.hour + (totalMinutes / 60);
        int finalMinutes = totalMinutes % 60;
        int finalHours = totalHours % 24; // Normalized to 24-hour cycle

        return new Time(finalHours, finalMinutes);
    }

    // Main method to test Time operations
    public static void main(String[] args) {
        Time t1 = new Time(2, 45);
        Time t2 = new Time(3, 30);

        System.out.print("Time 1: ");
        t1.display();

        System.out.print("Time 2: ");
        t2.display();

        Time sum = t1.addition(t2);
        System.out.print("Added Time (Time 1 + Time 2): ");
        sum.display();
    }
}
```

