### Constructor Overloading – Complete Program

```java
public class Box {
    double length, width, height;

    // Constructor 1 – No arguments (default box 1x1x1)
    Box() {
        length = 1.0;
        width  = 1.0;
        height = 1.0;
        System.out.println("Default constructor called");
    }

    // Constructor 2 – One argument (cube: all sides equal)
    Box(double side) {
        length = width = height = side;
        System.out.println("Single-arg constructor (cube) called");
    }

    // Constructor 3 – All three dimensions
    Box(double length, double width, double height) {
        this.length = length;
        this.width  = width;
        this.height = height;
        System.out.println("Three-arg constructor called");
    }

    // Constructor 4 – Copy constructor
    Box(Box other) {
        this.length = other.length;
        this.width  = other.width;
        this.height = other.height;
        System.out.println("Copy constructor called");
    }

    double volume() {
        return length * width * height;
    }

    void display() {
        System.out.printf("  Box: %.1f x %.1f x %.1f | Volume: %.2f%n",
                           length, width, height, volume());
    }

    public static void main(String[] args) {
        Box b1 = new Box();             // Constructor 1
        b1.display();

        Box b2 = new Box(5.0);          // Constructor 2
        b2.display();

        Box b3 = new Box(4.0, 3.0, 2.0); // Constructor 3
        b3.display();

        Box b4 = new Box(b3);           // Constructor 4 (copy)
        b4.display();
    }
}
```

