import java.awt.*;
import java.awt.event.*;
import java.io.*;

public class BusReservationGUI extends Frame {
    TextField txtName = new TextField(15);
    TextField txtAge = new TextField(5);
    Choice category = new Choice();
    Label lblStatus = new Label("Fill details and book ticket.");
    static int ticketCounter = 1000;

    BusReservationGUI() {
        setTitle("MGIT Bus Ticket Reservation");
        setLayout(new GridLayout(5, 2, 8, 8));

        category.add("General");
        category.add("Senior Citizen (30% off)");
        category.add("Child (50% off)");
        category.add("Armed Forces (40% off)");

        Button btnBook = new Button("Book Ticket");

        add(new Label("Passenger Name:")); add(txtName);
        add(new Label("Age:"));            add(txtAge);
        add(new Label("Category:"));       add(category);
        add(btnBook);                      add(lblStatus);

        btnBook.addActionListener(e -> bookTicket());

        setSize(400, 220);
        setVisible(true);
    }

    void bookTicket() {
        try {
            String name = txtName.getText().trim();
            if (name.isEmpty()) throw new IllegalArgumentException("Name cannot be empty.");

            int age = Integer.parseInt(txtAge.getText().trim());
            if (age <= 0 || age > 120) throw new IllegalArgumentException("Invalid age.");

            int ticketId = ++ticketCounter;
            double baseFare = 500.0;
            String cat = category.getSelectedItem();
            double fare = baseFare;

            if (cat.contains("Senior Citizen")) fare *= 0.70;
            else if (cat.contains("Child")) fare *= 0.50;
            else if (cat.contains("Armed Forces")) fare *= 0.60;

            String record = "Ticket #" + ticketId + " | Name: " + name + " | Age: " + age + " | Fare: Rs. " + fare;

            try (FileWriter fw = new FileWriter("bus_bookings.txt", true)) {
                fw.write(record + "
");
            }

            lblStatus.setText("Booked: ID #" + ticketId + " (Rs. " + fare + ")");
        } catch (Exception ex) {
            lblStatus.setText("Error: " + ex.getMessage());
        }
    }

    public static void main(String[] args) {
        new BusReservationGUI();
    }
}
